#[path="../src/bulk_price_screen.rs"]mod bulk_price_screen;
use bulk_price_screen::*;
use moloch_live_runtime::feedback;
use baal_transport_service::{Endpoint,Receipt,Scope};
use serde_json::{json,Value};
const NOW:u64=1_792_055_000_000;
const T:&str="11111111-1111-4111-8111-111111111111";
fn iso(t:u64)->String{chrono::DateTime::from_timestamp_millis(t as i64).unwrap().to_rfc3339_opts(chrono::SecondsFormat::Millis,true)}
fn scope(n:u64)->Scope{Scope{tournament_id:T.into(),tournament_slug:"cup".into(),exchanges:(1..=n).map(|n|(n.to_string(),(100+n).to_string())).collect()}}
fn ids(n:u64)->Vec<String>{(1..=n).map(|n|n.to_string()).collect()}
fn row(n:u64,bid:f64,ask:f64)->Value{json!({"exchangeId":n.to_string(),"marketId":(100+n).to_string(),"option":"YES","latestPrice":null,"bestBid":bid,"bestAsk":ask,"spread":null})}
fn receipt(n:u64)->Receipt{Receipt{endpoint:format!("/exchanges/prices?ids={}&tournamentId={T}",ids(n).join(",")),request_started_at:iso(NOW-100),received_at:iso(NOW),status:200,data:json!({"data":(1..=n).map(|n|row(n,0.4,0.45)).collect::<Vec<_>>(),"missingIds":[]})}}
fn quote(n:u64,side:&str,action:&str,p:&str)->Value{json!({"id":n,"exchangeId":n.to_string(),"marketId":(100+n).to_string(),"side":side,"action":action,"price":p,"quantity":100,"filled":0,"createdAt":NOW-10000,"activationAt":NOW-7000,"expiresAt":NOW+600000,"retired":false})}
#[test]fn twenty_far_native_shaped_quotes_share_one_original_price_read_without_any_book_or_account_claim(){
 let s=scope(20);let mut calls=Vec::new();let ep=endpoint(&s,&ids(20)).unwrap();calls.push(serde_json::to_value(ep).unwrap());let original=receipt(20);let b=Batch::from_original(&s,&ids(20),&original,NOW).unwrap();
 let quotes:Vec<_>=(1..=20).map(|n|quote(n,"YES","sell","0.905000")).collect();let mut deferred=0;for q in &quotes{let d=b.defer(&s,q,NOW).unwrap().unwrap();assert!(d.matches_quote(&s,q,NOW).unwrap());assert_eq!(d.reason(),"sell_floor_above_current_ask");deferred+=1;}
 assert_eq!(calls.len(),1);assert_eq!(calls[0]["kind"],"prices");assert_eq!(deferred,20);assert_eq!(b.receipt_sha256(),moloch_live_runtime::feedback::digest(&original).unwrap());
 // Counterfactual admission count only: 20 separate book screens versus 1
 // bulk observation. No live latency, depth, actual fill or profit is inferred.
 assert_eq!(20usize-calls.len(),19);
}
#[test]fn competitive_or_marketable_quotes_still_need_independent_full_book_and_account_facts(){let s=scope(1);let b=Batch::from_original(&s,&ids(1),&receipt(1),NOW).unwrap();for q in [quote(1,"YES","buy","0.400000"),quote(1,"YES","sell","0.450000"),quote(1,"YES","sell","0.400000"),quote(1,"NO","buy","0.550000"),quote(1,"NO","sell","0.600000")]{assert!(b.defer(&s,&q,NOW).unwrap().is_none());}}
#[test]fn no_prices_are_exact_yes_complements_not_latest_trade_or_spread(){let s=scope(1);let mut r=receipt(1);r.data["data"][0]["latestPrice"]=json!(0.99);r.data["data"][0]["spread"]=json!(0.005);let b=Batch::from_original(&s,&ids(1),&r,NOW).unwrap();assert!(b.defer(&s,&quote(1,"NO","sell","0.605000"),NOW).unwrap().is_some());assert_eq!(b.defer(&s,&quote(1,"NO","buy","0.545000"),NOW).unwrap().unwrap().reason(),"buy_behind_current_best_bid");assert_eq!(b.defer(&s,&quote(1,"NO","buy","0.600000"),NOW).unwrap().unwrap().reason(),"new_buy_would_cross_current_ask");}
#[test]fn null_missing_ambiguous_and_locked_prices_fall_back_instead_of_rejecting_a_quote(){let s=scope(1);for mode in 0..7{let mut r=receipt(1);match mode{0=>r.data["data"][0]["bestBid"]=Value::Null,1=>r.data["data"][0]["bestAsk"]=Value::Null,2=>r.data["data"][0]["option"]=Value::Null,3=>r.data["data"][0]["option"]=json!("NO"),4=>{r.data["data"]=json!([]);r.data["missingIds"]=json!(["1"])},5=>r.data["data"][0]["bestBid"]=json!(0.45),_=>r.data["data"][0]["bestAsk"]=json!(1.0)};let b=Batch::from_original(&s,&ids(1),&r,NOW).unwrap();assert!(b.defer(&s,&quote(1,"YES","sell","0.905000"),NOW).unwrap().is_none(),"{mode}");}}
#[test]fn lifetime_uses_original_request_start_and_cannot_be_renewed_by_reminting_or_changed_quote(){let s=scope(1);let r=receipt(1);let b=Batch::from_original(&s,&ids(1),&r,NOW).unwrap();let q=quote(1,"YES","sell","0.905000");let d=b.defer(&s,&q,NOW).unwrap().unwrap();assert_eq!(d.valid_until_ms(),NOW+1400);assert!(d.matches_quote(&s,&q,NOW+1399).unwrap());assert!(!d.matches_quote(&s,&q,NOW+1400).unwrap());for field in ["price","quantity","expiresAt"]{let mut changed=q.clone();changed[field]=match field{"price"=>json!("0.900000"),"quantity"=>json!(99),_=>json!(NOW+600001)};assert!(!d.matches_quote(&s,&changed,NOW).unwrap());}let old=Batch::from_original(&s,&ids(1),&r,NOW+100000).unwrap();assert!(old.defer(&s,&q,NOW+100000).unwrap().is_none());assert_eq!(old.valid_until_ms(),b.valid_until_ms());assert!(b.defer(&s,&q,NOW-1).unwrap().is_none());}
#[test]fn risk_and_dedicated_forecast_quotes_never_receive_an_ordinary_bulk_veto(){let s=scope(1);let b=Batch::from_original(&s,&ids(1),&receipt(1),NOW).unwrap();for field in ["inventoryExitReason","executionStyle","reviewedInventoryExit","reviewedFundamentalEntry"]{let mut q=quote(1,"YES","sell","0.905000");q[field]=match field{"inventoryExitReason"=>json!("maximumAge"),"executionStyle"=>json!("inventoryAON"),_=>json!({"reviewSha256":"a".repeat(64)})};assert!(b.defer(&s,&q,NOW).unwrap().is_none());}}
#[test]fn wrong_scope_endpoint_tournament_duplicates_coverage_and_future_clocks_are_not_negative_evidence(){let s=scope(2);for mode in 0..12{let mut r=receipt(2);match mode{0=>r.endpoint.push_str("&extra=true"),1=>r.endpoint=r.endpoint.replace(T,"other"),2=>r.data["data"][0]["marketId"]=json!("999"),3=>r.data["data"][0]["exchangeId"]=json!("999"),4=>r.data["data"][1]=r.data["data"][0].clone(),5=>{r.data["data"].as_array_mut().unwrap().pop();},6=>r.data["missingIds"]=json!(["1"]),7=>r.request_started_at=iso(NOW+1),8=>r.received_at=iso(NOW+1),9=>r.status=503,10=>r.data["data"][0]["bestBid"]=json!("0.400000"),_=>r.data["data"][0]["bestAsk"]=json!(0.451)}assert!(Batch::from_original(&s,&ids(2),&r,NOW).is_err(),"{mode}");}}
#[test]fn request_max100_unique_numeric_scoped_ids_and_exact_scope_remain_mandatory(){let s=scope(101);for raw in [vec![],ids(101),vec!["1".into(),"1".into()],vec!["102".into()],vec!["01".into()]]{assert!(endpoint(&s,&raw).is_err());}assert!(matches!(endpoint(&s,&ids(100)).unwrap(),Endpoint::Prices{exchange_ids}if exchange_ids.len()==100));let b=Batch::from_original(&s,&ids(1),&receipt(1),NOW).unwrap();let mut other=s.clone();other.tournament_slug="other".into();assert!(b.defer(&other,&quote(1,"YES","sell","0.905000"),NOW).is_err());}
#[test]fn canonical_binary_tick_is_not_a_general_rounding_tolerance(){let s=scope(1);let mut r=receipt(1);r.data["data"][0]["bestBid"]=json!(0.06000000000000005);r.data["data"][0]["bestAsk"]=json!(0.065);assert!(Batch::from_original(&s,&ids(1),&r,NOW).is_ok());r.data["data"][0]["bestBid"]=json!(0.0600000001);assert!(Batch::from_original(&s,&ids(1),&r,NOW).is_err());}

#[test]fn original_derived_ieee_spread_uses_the_verified_tick_bbo_without_rewriting_receipt(){let s=scope(1);let mut r=receipt(1);let bid=1.0f64-0.94f64;let ask=0.065f64;r.data["data"][0]["bestBid"]=json!(bid);r.data["data"][0]["bestAsk"]=json!(ask);r.data["data"][0]["spread"]=json!(ask-bid);let original=r.clone();let b=Batch::from_original(&s,&ids(1),&r,NOW).unwrap();assert!(b.defer(&s,&quote(1,"YES","sell","0.905000"),NOW).unwrap().is_some());assert_eq!(serde_json::to_value(&r).unwrap(),serde_json::to_value(&original).unwrap());assert_eq!(b.receipt_sha256(),feedback::digest(&original).unwrap());r.data["data"][0]["spread"]=json!(f64::from_bits((ask-bid).to_bits()+1));assert!(Batch::from_original(&s,&ids(1),&r,NOW).is_err());}
